/**
 * Порт репозитория каталога.
 *
 * Объявлен в domain, реализуется в infrastructure (ADR-0001).
 * Здесь нет ни SQL, ни типов драйвера БД.
 */

import type { Game, GamePlatform, GameUpsertInput } from './game.js';

export interface GamePlatformInput extends Omit<GamePlatform, 'metascore' | 'userscore'> {
