    const sortColumn = sortColumns[query.sortBy ?? 'metascore'] ?? 'g.metascore_overall';
    const direction = query.sortDirection === 'asc' ? 'ASC' : 'DESC';
    const nulls = direction === 'ASC' ? 'NULLS FIRST' : 'NULLS LAST';

    const countResult = await this.pool.query<{ count: string }>(
      `SELECT count(*)::text AS count FROM games g ${where}`,
      params,
    );

    params.push(limit, offset);
    const { rows } = await this.pool.query<GameRow>(
      `SELECT ${GAME_COLUMNS.replace(/\b(\w+)/g, 'g.$1')}
       FROM games g
       ${where}
       ORDER BY ${sortColumn} ${direction} ${nulls}, g.id
       LIMIT $${params.length - 1} OFFSET $${params.length}`,
      params,
    );

    return {
      items: rows.map(mapGame),
      total: Number(countResult.rows[0]?.count ?? 0),
    };
  }

  async replacePlatforms(
    gameId: string,
    platforms: readonly GamePlatformInput[],
  ): Promise<void> {
    // Полная замена в транзакции: набор платформ игры реконсилируется целиком,
    // чтобы исчезнувшая платформа не осталась в базе навсегда.
    await withTransaction(this.pool, async (client) => {
      await client.query('DELETE FROM game_platforms WHERE game_id = $1', [gameId]);

      for (const p of platforms) {
        await client.query(
          `INSERT INTO game_platforms (
             game_id, platform_slug, platform_name,
             metascore, metascore_scope, userscore, userscore_scope,
             critic_count, user_count, updated_at
           ) VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9, now())`,
          [
            gameId,
            p.platformSlug,
            p.platformName,
            p.metascore,
            p.metascoreScope,
            p.userscore,
            p.userscoreScope,
            p.criticCount,
            p.userCount,
          ],
        );
      }
    });
  }

  async findPlatforms(gameId: string): Promise<readonly GamePlatform[]> {
    const { rows } = await this.pool.query<PlatformRow>(
      `SELECT platform_slug, platform_name, metascore, metascore_scope,
              userscore, userscore_scope, critic_count, user_count
       FROM game_platforms
       WHERE game_id = $1
       ORDER BY platform_slug`,
      [gameId],
    );
    return rows.map(mapPlatform);
  }

  async listDistinctPlatforms(): Promise<readonly { slug: string; name: string }[]> {
    const { rows } = await this.pool.query<{ platform_slug: string; platform_name: string }>(
      `SELECT DISTINCT platform_slug, platform_name
       FROM game_platforms
       ORDER BY platform_name`,
    );
    return rows.map((r) => ({ slug: r.platform_slug, name: r.platform_name }));
  }
}

