    const { rows } = await this.pool.query<RunRow>(
      `INSERT INTO runs (trigger, status, owner_id, lock_key, heartbeat_at)
       VALUES ($1, 'running', $2, $3, now())
       RETURNING ${RUN_COLUMNS}`,
