50	const DEFAULT_TIMEOUT_MS = 15_000;
51	const DEFAULT_MAX_ATTEMPTS = 3;
52	const DEFAULT_RPS = 1;
53	const DEFAULT_MAX_RETRY_AFTER_MS = 60_000;
54	const BASE_BACKOFF_MS = 1_000;
