59	export class MetacriticHttpClient {
60	  private readonly baseUrl: string;
61	  private readonly userAgent: string;
62	  private readonly timeoutMs: number;
63	  private readonly maxAttempts: number;
64	  private readonly maxRetryAfterMs: number;
65	  private readonly logger: Logger;
66	  private readonly fetchImpl: typeof fetch;
67	  private readonly sleep: (ms: number) => Promise<void>;
68	  private readonly limiter: TokenBucketRateLimiter;
69	  private readonly random: () => number;
70	
71	  constructor(options: MetacriticHttpClientOptions) {
72	    this.baseUrl = (options.baseUrl ?? DEFAULT_BASE_URL).replace(/\/$/, '');
73	    this.userAgent = options.userAgent;
74	    this.timeoutMs = options.timeoutMs ?? DEFAULT_TIMEOUT_MS;
75	    this.maxAttempts = options.maxAttempts ?? DEFAULT_MAX_ATTEMPTS;
76	    this.maxRetryAfterMs = options.maxRetryAfterMs ?? DEFAULT_MAX_RETRY_AFTER_MS;
77	    this.logger = options.logger ?? silentLogger;
78	    this.fetchImpl = options.fetchImpl ?? globalThis.fetch;
79	    this.sleep = options.sleep ?? defaultSleep;
80	    this.random = options.random ?? Math.random;
81	    this.limiter =
82	      options.rateLimiter ??
83	      new TokenBucketRateLimiter({
84	        requestsPerSecond: options.requestsPerSecond ?? DEFAULT_RPS,
85	        ...options.rateLimiterOptions,
86	      });
87	
88	    if (!this.userAgent || this.userAgent.trim().length === 0) {
89	      throw new Error('userAgent обязателен: бот должен честно представляться');
90	    }
91	  }
92	
93	  resolveUrl(path: string): string {
94	    if (path.startsWith('http://') || path.startsWith('https://')) return path;
95	    return `${this.baseUrl}${path.startsWith('/') ? path : `/${path}`}`;
96	  }
97	
98	  async get(path: string, signal?: AbortSignal): Promise<HttpFetchResult> {
99	    const url = this.resolveUrl(path);
100	    const startedAt = Date.now();
101	    let lastError: IngestionError | null = null;
102	
103	    for (let attempt = 1; attempt <= this.maxAttempts; attempt += 1) {
104	      throwIfAborted(signal);
105	      await this.limiter.acquire(signal);
106	
107	      try {
108	        const result = await this.attempt(url, attempt, signal, startedAt);
109	
110	        this.logger.info('Запрос к источнику выполнен', {
111	          source: 'metacritic',
112	          operation: 'http_get',
113	          url,
114	          status: result.status,
115	          durationMs: result.durationMs,
116	          attempts: attempt,
117	          // Размер, а не содержимое: полный HTML в логи не попадает
118	          responseBytes: result.body.length,
119	        });
120	
121	        return result;
122	      } catch (error) {
123	        if (isAbortError(error)) {
124	          throw new IngestionError('aborted', 'Запрос отменён', { url, attempt });
125	        }
126	
127	        const ingestionError = toIngestionError(error, url, attempt);
128	        lastError = ingestionError;
129	
130	        // Блокировка и клиентские ошибки повторам не подлежат.
131	        if (!ingestionError.retryable || attempt >= this.maxAttempts) {
132	          this.logger.warn('Запрос к источнику завершился ошибкой', {
133	            source: 'metacritic',
134	            operation: 'http_get',
135	            url,
136	            attempts: attempt,
