/**
 * Порт репозитория каталога.
 *
 * Объявлен в domain, реализуется в infrastructure (ADR-0001).
 * Здесь нет ни SQL, ни типов драйвера БД.
 */

import type { Game, GamePlatform, GameUpsertInput } from './game.js';

export interface GamePlatformInput extends Omit<GamePlatform, 'metascore' | 'userscore'> {
  readonly metascore: number | null;
  readonly userscore: number | null;
}

export type GameSortField = 'metascore' | 'userscore' | 'releaseDate' | 'title';
export type SortDirection = 'asc' | 'desc';

export interface GameListQuery {
  readonly search?: string;
  readonly platformSlugs?: readonly string[];
  readonly sortBy?: GameSortField;
  readonly sortDirection?: SortDirection;
  readonly limit?: number;
  readonly offset?: number;
}

export interface GameListResult {
  readonly items: readonly Game[];
  readonly total: number;
}

export interface GameRepository {
  /**
   * Создаёт или обновляет игру по natural key (source, source_slug).
   * Существующая игра обновляется, а не дублируется — требование ТЗ.
   * first_seen_at при обновлении сохраняется.
   */
  upsert(input: GameUpsertInput): Promise<Game>;

  findById(id: string): Promise<Game | null>;

  findBySlug(source: string, sourceSlug: string): Promise<Game | null>;

  list(query: GameListQuery): Promise<GameListResult>;

  /** Полностью заменяет набор платформ игры (реконсиляция при повторном обходе). */
  replacePlatforms(
    gameId: string,
    platforms: readonly GamePlatformInput[],
  ): Promise<void>;

  findPlatforms(gameId: string): Promise<readonly GamePlatform[]>;

  /** Список платформ, встречающихся в каталоге, — для фильтра в UI. */
  listDistinctPlatforms(): Promise<readonly { slug: string; name: string }[]>;
}

