15	  type IngestionEventSink,
16	} from '../domain/ingestion-events.js';
17	
18	/**
19	 * Ingestion одной игры: получение из источника и сохранение в каталог.
20	 *
21	 * Слой application работает только с портами. Здесь нет ни cheerio, ни HTML,
22	 * ни HTTP, ни SQL — они спрятаны за GameCatalogSource и репозиториями
23	 * (ADR-0001).
24	 *
25	 * Порядок операций (ADR-0011):
26	 *   1) сеть — ВНЕ транзакции;
27	 *   2) транзакция: upsert игры + синхронизация платформ;
28	 *   3) при ошибке — откат, частичного сохранения не остаётся.
29	 */
30	
31	export interface IngestGameDeps {
32	  readonly catalogSource: GameCatalogSource;
33	  readonly games: GameRepository;
34	  readonly platforms: GamePlatformRepository;
35	  readonly unitOfWork: UnitOfWork;
36	  readonly events?: IngestionEventSink;
37	  /** Источник времени — подменяется в тестах. */
38	  readonly now?: () => number;
39	}
40	
41	export interface IngestGameParams {
42	  readonly sourceSlug: string;
43	  readonly signal?: AbortSignal;
44	}
45	
46	export interface IngestGameResult {
47	  readonly gameId: string;
48	  readonly created: boolean;
49	  readonly platformsCreated: number;
50	  readonly platformsUpdated: number;
51	  readonly platformsDeactivated: number;
52	  readonly platformsReactivated: number;
53	  readonly durationMs: number;
54	}
