56	/**
57	 * Преобразует нормализованные данные источника в модель хранения.
58	 *
59	 * Инварианты, которые обязаны сохраниться при переносе:
60	 * - developer и publishers остаются РАЗДЕЛЬНЫМИ полями; издатель никогда не
61	 *   подставляется вместо разработчика (ADR-0003);
62	 * - metascore = null означает 'tbd' и не превращается в 0;
63	 * - userscore не разносится по платформам (ADR-0008).
64	 */
65	export function toGameUpsertInput(game: NormalizedGame): GameUpsertInput {
66	  return {
67	    source: game.source,
68	    sourceSlug: game.sourceSlug,
69	    sourceUrl: game.canonicalUrl,
70	    parserVersion: game.parserVersion,
71	    title: game.title,
72	    description: game.description,
73	    coverUrl: game.coverImageUrl,
74	    trailerUrl: game.videoUrl,
75	    // Разработчик — только из собственного поля источника
76	    developer: game.developer,
77	    developerStatus: game.developerStatus,
78	    // Издатели хранятся отдельно и не участвуют в вычислении developer
79	    publishers: game.publishers,
80	    genres: game.genres,
81	    releaseDate: game.releaseDate,
82	    metascoreOverall: game.metascoreOverall,
83	    userscoreOverall: game.userscoreOverall,
84	  };
85	}
