88	  return game.platforms.map((platform) => ({
89	    platformSlug: platform.platform,
90	    platformName: platform.platformName,
91	    // null сохраняется как null: 'tbd' не является нулевой оценкой
92	    metascore: platform.metascore,
93	    metascoreScope: platform.metascoreScope,
