102	export class IngestGameUseCase {
103	  private readonly events: IngestionEventSink;
104	  private readonly now: () => number;
105	
106	  constructor(private readonly deps: IngestGameDeps) {
107	    this.events = deps.events ?? noopEventSink;
108	    this.now = deps.now ?? (() => Date.now());
