110	
111	  async execute(params: IngestGameParams): Promise<IngestGameResult> {
112	    const startedAt = this.now();
113	    const source = this.deps.catalogSource.source;
114	    const sourceSlug = params.sourceSlug.trim().toLowerCase();
115	
116	    this.events.emit({ type: 'ingestion_started', source, sourceSlug });
117	
118	    // --- Шаг 1: сеть. Выполняется ВНЕ транзакции, чтобы медленный HTTP
119	    // не удерживал соединение с БД и не порождал распределённых транзакций.
120	    let normalized: NormalizedGame;
121	    try {
122	      normalized = await this.deps.catalogSource.fetchGame({
