    kind: params.kind,
    platformSlug,
    reviews: collected,
    totalAvailable,
    completeness: resolveCompleteness({
      stopReason,
      sourceFailed,
      malformed,
      collected: collected.length,
      totalAvailable,
    }),
    malformed,
    pagesScanned,
    stopReason,
  };
}

