        params.gameId,
        params.kind,
        params.platformSlug,
        identity.externalId,
        identity.publicationSlug,
        review.score,
        review.quote,
        review.author,
        review.reviewUrl,
        review.reviewDate,
        review.sourceVersion,
        review.spoiler,
        contentHash,
      ],
    );

    if (previousHash === undefined) created += 1;
    else if (previousHash !== contentHash) updated += 1;
    else unchanged += 1;
  }

  return { created, updated, unchanged };
}

