import { z } from 'zod';
import {
  LlmError,
  type AnalysisPoint,
  type LlmAnalysisContent,
  type PreparedReview,
} from '../domain/llm-provider.js';

/**
 * Проверка ответа модели.
 *
 * Вывод модели остаётся НЕДОВЕРЕННЫМ даже после разбора: схема ограничивает
 * его форму, но не гарантирует правдивость. Поэтому проверок две ступени —
 * структура и ссылки на свидетельства.
 *
 * Схема объявлена в ОДНОМ месте и переиспользуется провайдером: дублирование
 * привело бы к расхождению между тем, что просим, и тем, что принимаем.
 */

const evidenceRefSchema = z
  .string()
  .regex(/^r\d+$/, 'Ссылка должна иметь вид r<номер>');

const pointSchema = z.object({
  text: z.string().min(1).max(300),
  evidenceRefs: z.array(evidenceRefSchema).min(1).max(10),
});

const themeSchema = z.object({
  name: z.string().min(1).max(80),
  sentiment: z.enum(['positive', 'negative', 'neutral', 'mixed']),
  description: z.string().min(1).max(400),
  evidenceRefs: z.array(evidenceRefSchema).min(1).max(10),
});

/** Схема ответа. Единственный источник истины о его форме. */
export const analysisOutputSchema = z
  .object({
    summary: z.string().min(10).max(800),
    liked: z.array(pointSchema).max(8),
    disliked: z.array(pointSchema).max(8),
    themes: z.array(themeSchema).max(10),
    confidence: z.enum(['low', 'medium', 'high']),
  })
  // Лишние поля отклоняются: модель не должна расширять контракт.
  .strict();

export type ValidatedOutput = z.infer<typeof analysisOutputSchema>;

/** JSON Schema для передачи провайдеру — выводится из той же зод-схемы. */
export const ANALYSIS_JSON_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['summary', 'liked', 'disliked', 'themes', 'confidence'],
  properties: {
    summary: { type: 'string', minLength: 10, maxLength: 800 },
    liked: {
      type: 'array',
      maxItems: 8,
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['text', 'evidenceRefs'],
        properties: {
          text: { type: 'string', minLength: 1, maxLength: 300 },
          evidenceRefs: {
            type: 'array',
            minItems: 1,
            maxItems: 10,
            items: { type: 'string', pattern: '^r[0-9]+$' },
          },
        },
      },
    },
    disliked: {
      type: 'array',
      maxItems: 8,
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['text', 'evidenceRefs'],
        properties: {
          text: { type: 'string', minLength: 1, maxLength: 300 },
          evidenceRefs: {
            type: 'array',
            minItems: 1,
            maxItems: 10,
            items: { type: 'string', pattern: '^r[0-9]+$' },
          },
        },
      },
    },
    themes: {
      type: 'array',
      maxItems: 10,
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['name', 'sentiment', 'description', 'evidenceRefs'],
        properties: {
          name: { type: 'string', minLength: 1, maxLength: 80 },
          sentiment: { enum: ['positive', 'negative', 'neutral', 'mixed'] },
          description: { type: 'string', minLength: 1, maxLength: 400 },
          evidenceRefs: {
            type: 'array',
            minItems: 1,
            maxItems: 10,
            items: { type: 'string', pattern: '^r[0-9]+$' },
          },
        },
      },
    },
    confidence: { enum: ['low', 'medium', 'high'] },
  },
