import Anthropic from '@anthropic-ai/sdk';
import { zodOutputFormat } from '@anthropic-ai/sdk/helpers/zod';
import { silentLogger, type Logger } from '../../../shared/logging/logger.js';
import {
  LlmError,
  type LlmAnalysisRequest,
  type LlmAnalysisResult,
  type LlmProvider,
} from '../domain/llm-provider.js';
import {
  analysisOutputSchema,
  toAnalysisContent,
  validateEvidence,
} from '../application/validate-output.js';
import { buildSystemPrompt, buildUserPrompt } from './prompts.js';

/**
 * Провайдер Anthropic.
 *
 * Единственное место, где проект знает про SDK: application работает через
 * порт LlmProvider (ADR-0006).
 *
 * Схема ответа задаётся через output_config.format из ТОЙ ЖЕ zod-схемы, что
 * используется для проверки. Дублировать её отдельным описанием нельзя:
 * расхождение между «что просим» и «что принимаем» осталось бы незамеченным.
 */

export interface AnthropicLlmProviderOptions {
  readonly apiKey: string;
  readonly model: string;
  readonly timeoutMs: number;
  readonly maxOutputTokens: number;
  readonly logger?: Logger;
  /** Подменяется в тестах на поддельный клиент. */
  readonly client?: Anthropic;
}

export class AnthropicLlmProvider implements LlmProvider {
  readonly model: string;

  private readonly client: Anthropic;
  private readonly logger: Logger;
  private readonly timeoutMs: number;

  constructor(options: AnthropicLlmProviderOptions) {
    if (!options.apiKey || options.apiKey.trim().length === 0) {
      // Ключ обязателен и приходит только из окружения: в коде его нет.
      throw new Error('LLM_API_KEY не задан: провайдер не может быть создан');
    }

    this.model = options.model;
    this.timeoutMs = options.timeoutMs;
    this.logger = options.logger ?? silentLogger;
    this.client =
      options.client ??
      new Anthropic({
        apiKey: options.apiKey,
        timeout: options.timeoutMs,
        // Повторы выполняет наш use case: у него своя политика по категориям
        // ошибок, и двойной механизм умножал бы задержки.
        maxRetries: 0,
      });
  }

  async analyzeReviews(request: LlmAnalysisRequest): Promise<LlmAnalysisResult> {
    const startedAt = Date.now();

    try {
      const response = await this.client.messages.parse(
        {
          model: this.model,
          max_tokens: request.maxOutputTokens,
          system: buildSystemPrompt(request.kind),
          messages: [{ role: 'user', content: buildUserPrompt(request) }],
          output_config: { format: zodOutputFormat(analysisOutputSchema) },
        },
        request.signal ? { signal: request.signal } : undefined,
      );

      const parsed = response.parsed_output;
      if (!parsed) {
        // Модель ответила, но вывод не подошёл под схему.
        throw new LlmError('schema_invalid', 'Ответ модели не разобран по схеме');
      }

      // Ссылки проверяются здесь же: результат с несуществующей ссылкой не
      // должен покинуть провайдер как валидный.
      validateEvidence(parsed, request.reviews);

      this.logger.info('Анализ отзывов выполнен', {
        operation: 'llm_analyze',
        kind: request.kind,
        model: response.model,
        inputCount: request.reviews.length,
        durationMs: Date.now() - startedAt,
        // Ни промпт, ни ответ, ни тексты отзывов в лог не попадают
        tokensIn: response.usage?.input_tokens ?? null,
        tokensOut: response.usage?.output_tokens ?? null,
      });

      if (response.stop_reason === 'max_tokens') {
        throw new LlmError(
          'token_limit',
          'Ответ обрезан по лимиту токенов: требуется уменьшить выборку',
        );
      }

      return {
        content: toAnalysisContent(parsed),
        // Фактическая модель из ответа: она входит в ключ идемпотентности.
        model: response.model ?? this.model,
        usage: {
          inputTokens: response.usage?.input_tokens ?? null,
          outputTokens: response.usage?.output_tokens ?? null,
        },
      };
    } catch (error) {
      throw toLlmError(error);
    }
  }
}

/**
 * Приводит ошибку SDK к типизированной категории.
 *
 * Категория определяет, имеет ли смысл повтор: таймаут повторить стоит,
 * невалидный ответ — почти наверняка нет.
 */
export function toLlmError(error: unknown): LlmError {
  if (error instanceof LlmError) return error;

  if (error instanceof Anthropic.APIUserAbortError) {
    return new LlmError('aborted', 'Запрос к модели отменён', { cause: error });
  }

  if (error instanceof Anthropic.APIConnectionTimeoutError) {
    return new LlmError('timeout', 'Истекло время ожидания ответа модели', {
      cause: error,
    });
  }

  if (error instanceof Anthropic.APIConnectionError) {
    return new LlmError('unavailable', 'Провайдер модели недоступен', { cause: error });
  }

  if (error instanceof Anthropic.RateLimitError) {
    const retryAfter = parseRetryAfter(error.headers);
    return new LlmError('rate_limited', 'Превышен лимит запросов к модели', {
      cause: error,
      ...(retryAfter !== undefined ? { retryAfterMs: retryAfter } : {}),
    });
  }

  if (error instanceof Anthropic.APIError) {
    const status = error.status ?? 0;

    if (status >= 500) {
      return new LlmError('server_error', `Ошибка провайдера (${status})`, {
        cause: error,
      });
    }

    // Прочие 4xx повтором не лечатся: запрос сформирован неверно либо
    // отклонён по существу.
    return new LlmError('client_error', `Запрос отклонён провайдером (${status})`, {
      cause: error,
    });
  }

  const message = error instanceof Error ? error.message : String(error);
  return new LlmError('unavailable', `Непредвиденная ошибка провайдера: ${message}`, {
    cause: error,
  });
}

/** Извлекает Retry-After из заголовков ответа. */
function parseRetryAfter(headers: unknown): number | undefined {
  if (!headers || typeof headers !== 'object') return undefined;

  const get = (headers as { get?: (name: string) => string | null }).get;
  const raw = typeof get === 'function' ? get.call(headers, 'retry-after') : null;
  if (!raw) return undefined;

  const seconds = Number(raw);
  return Number.isFinite(seconds) && seconds >= 0 ? Math.round(seconds * 1000) : undefined;
