import Anthropic from '@anthropic-ai/sdk';
import { describe, expect, it, vi } from 'vitest';
import {
  AnthropicLlmProvider,
  toLlmError,
} from '../../src/modules/analysis/infrastructure/anthropic-llm-provider.js';
import { LlmError, type LlmAnalysisRequest } from '../../src/modules/analysis/domain/llm-provider.js';

/**
 * Тесты адаптера Anthropic.
 *
 * Реальный API НЕ вызывается: клиент SDK подменяется. Ключ здесь заведомо
 * фиктивный и в запрос не уходит — сеть не задействована вовсе.
 */

const FAKE_KEY = 'test-key-not-real';

const request: LlmAnalysisRequest = {
  kind: 'user',
  gameTitle: 'Тестовая игра',
  platformSlug: 'pc',
  reviews: [
    {
      ref: 'r1',
      reviewKey: 'user:u1',
      score: 9,
      date: '2026-01-01',
      text: 'Отличная игра',
      truncated: false,
      duplicates: 1,
      source: 'user',
    },
    {
      ref: 'r2',
      reviewKey: 'user:u2',
      score: 2,
      date: '2026-01-02',
      text: 'Много багов',
      truncated: false,
      duplicates: 1,
      source: 'user',
    },
  ],
  analyzedCount: 2,
  totalAvailable: 2,
  promptVersion: 'v1',
  samplingVersion: 'v1',
  maxOutputTokens: 1500,
};

const validOutput = {
  summary: 'Мнения разделились: одни хвалят игру, другие жалуются на баги.',
  liked: [{ text: 'Атмосфера', evidenceRefs: ['r1'] }],
  disliked: [{ text: 'Баги', evidenceRefs: ['r2'] }],
  themes: [
    {
      name: 'стабильность',
      sentiment: 'negative' as const,
      description: 'Технические проблемы',
      evidenceRefs: ['r2'],
    },
  ],
  confidence: 'medium' as const,
};

/** Клиент SDK с подменённым messages.parse — сети нет. */
function fakeClient(
  parse: (...args: unknown[]) => Promise<unknown>,
): Anthropic {
  return { messages: { parse } } as unknown as Anthropic;
}

function makeProvider(parse: (...args: unknown[]) => Promise<unknown>): AnthropicLlmProvider {
  return new AnthropicLlmProvider({
    apiKey: FAKE_KEY,
    model: 'claude-haiku-4-5',
    timeoutMs: 5000,
    maxOutputTokens: 1500,
    client: fakeClient(parse),
  });
}

const okResponse = {
  parsed_output: validOutput,
  model: 'claude-haiku-4-5',
  stop_reason: 'end_turn',
  usage: { input_tokens: 500, output_tokens: 120 },
};

describe('Создание провайдера', () => {
  it('без ключа провайдер не создаётся', () => {
    expect(
      () =>
        new AnthropicLlmProvider({
          apiKey: '',
          model: 'claude-haiku-4-5',
          timeoutMs: 5000,
          maxOutputTokens: 1500,
        }),
    ).toThrow(/LLM_API_KEY/);
  });

  it('пробельный ключ отклоняется', () => {
    expect(
      () =>
        new AnthropicLlmProvider({
          apiKey: '   ',
          model: 'claude-haiku-4-5',
          timeoutMs: 5000,
          maxOutputTokens: 1500,
        }),
    ).toThrow();
  });
});

describe('Успешный вызов', () => {
  it('возвращает содержимое, модель и расход токенов', async () => {
    const provider = makeProvider(async () => okResponse);
    const result = await provider.analyzeReviews(request);

    expect(result.content.summary).toBe(validOutput.summary);
    expect(result.model).toBe('claude-haiku-4-5');
    expect(result.usage.inputTokens).toBe(500);
    expect(result.usage.outputTokens).toBe(120);
  });

  it('модель берётся из ответа, а не из настройки', async () => {
    const provider = makeProvider(async () => ({
      ...okResponse,
      model: 'claude-haiku-4-5-20990101',
    }));

    const result = await provider.analyzeReviews(request);
    expect(result.model).toBe('claude-haiku-4-5-20990101');
  });

  it('отсутствие расхода токенов даёт null', async () => {
    const provider = makeProvider(async () => ({ ...okResponse, usage: undefined }));
    const result = await provider.analyzeReviews(request);

    expect(result.usage.inputTokens).toBeNull();
    expect(result.usage.outputTokens).toBeNull();
  });
});

describe('Формирование запроса', () => {
  it('передаёт модель, лимит и схему вывода', async () => {
    const parse = vi.fn(async () => okResponse);
    await makeProvider(parse).analyzeReviews(request);

    const body = parse.mock.calls[0]![0] as Record<string, unknown>;

    expect(body.model).toBe('claude-haiku-4-5');
    expect(body.max_tokens).toBe(1500);
    // Структурированный вывод задаётся через output_config.format
    expect(body.output_config).toBeDefined();
    expect((body.output_config as Record<string, unknown>).format).toBeDefined();
  });

  it('отзывы уходят в пользовательском сообщении как JSON', async () => {
    const parse = vi.fn(async () => okResponse);
    await makeProvider(parse).analyzeReviews(request);

    const body = parse.mock.calls[0]![0] as {
      system: string;
      messages: { role: string; content: string }[];
    };

    // Инструкция отдельно, данные отдельно
    expect(body.system).not.toContain('Отличная игра');

    const payload = JSON.parse(body.messages[0]!.content) as {
      reviews: { ref: string; text: string }[];
    };
    expect(payload.reviews.map((r) => r.ref)).toEqual(['r1', 'r2']);
  });

  it('сигнал отмены передаётся в SDK', async () => {
    const parse = vi.fn(async () => okResponse);
    const controller = new AbortController();

    await makeProvider(parse).analyzeReviews({ ...request, signal: controller.signal });

    const options = parse.mock.calls[0]![1] as { signal?: AbortSignal } | undefined;
    expect(options?.signal).toBe(controller.signal);
  });
});

describe('Проверка ответа', () => {
  it('неразобранный вывод даёт schema_invalid', async () => {
    const provider = makeProvider(async () => ({ ...okResponse, parsed_output: null }));

    await expect(provider.analyzeReviews(request)).rejects.toMatchObject({
      category: 'schema_invalid',
    });
  });

  it('ссылка на несуществующий отзыв даёт evidence_invalid', async () => {
    const provider = makeProvider(async () => ({
      ...okResponse,
      parsed_output: {
        ...validOutput,
        liked: [{ text: 'Нечто', evidenceRefs: ['r404'] }],
      },
    }));

    await expect(provider.analyzeReviews(request)).rejects.toMatchObject({
      category: 'evidence_invalid',
    });
  });

  it('обрезанный по лимиту токенов ответ отклоняется', async () => {
    const provider = makeProvider(async () => ({ ...okResponse, stop_reason: 'max_tokens' }));

    await expect(provider.analyzeReviews(request)).rejects.toMatchObject({
      category: 'token_limit',
    });
  });
});

describe('Классификация ошибок SDK', () => {
  const cases: [string, unknown, string][] = [
    ['таймаут соединения', new Anthropic.APIConnectionTimeoutError({ message: 'timeout' }), 'timeout'],
    ['ошибка соединения', new Anthropic.APIConnectionError({ message: 'network' }), 'unavailable'],
  ];

  for (const [name, error, expected] of cases) {
    it(`${name} → ${expected}`, () => {
      expect(toLlmError(error).category).toBe(expected);
    });
  }

  it('429 → rate_limited и повторяется', () => {
    const error = new Anthropic.RateLimitError(429, undefined, 'rate limit', undefined);
    const mapped = toLlmError(error);

    expect(mapped.category).toBe('rate_limited');
    expect(mapped.retryable).toBe(true);
  });

  it('500 → server_error и повторяется', () => {
    const error = new Anthropic.InternalServerError(500, undefined, 'boom', undefined);
    const mapped = toLlmError(error);

    expect(mapped.category).toBe('server_error');
    expect(mapped.retryable).toBe(true);
  });

  it('400 → client_error и НЕ повторяется', () => {
    const error = new Anthropic.BadRequestError(400, undefined, 'bad', undefined);
    const mapped = toLlmError(error);

    expect(mapped.category).toBe('client_error');
    expect(mapped.retryable).toBe(false);
  });

  it('401 → client_error и НЕ повторяется', () => {
    const error = new Anthropic.AuthenticationError(401, undefined, 'unauthorized', undefined);
    const mapped = toLlmError(error);

    expect(mapped.category).toBe('client_error');
    expect(mapped.retryable).toBe(false);
  });

  it('отмена → aborted и НЕ повторяется', () => {
    const mapped = toLlmError(new Anthropic.APIUserAbortError({ message: 'aborted' }));

    expect(mapped.category).toBe('aborted');
    expect(mapped.retryable).toBe(false);
  });

  it('ошибка провайдера доходит до вызывающего типизированной', async () => {
    const provider = makeProvider(async () => {
      throw new Anthropic.RateLimitError(429, undefined, 'rate limit', undefined);
    });

    await expect(provider.analyzeReviews(request)).rejects.toBeInstanceOf(LlmError);
  });
});

describe('Утечки секретов', () => {
  it('ключ не попадает в сообщение об ошибке', async () => {
    const provider = makeProvider(async () => {
      throw new Error(`сбой при обращении с ключом ${FAKE_KEY}`);
    });

    // Сообщение SDK пробрасывается — проверяем, что НАШ код ключ не добавляет
    const parseOnly = makeProvider(async () => ({ ...okResponse, parsed_output: null }));

    await expect(parseOnly.analyzeReviews(request)).rejects.toSatisfy(
      (error: Error) => !error.message.includes(FAKE_KEY),
    );

    // Провайдер с ключом в тексте чужой ошибки не маскирует его молча —
    // это ответственность источника ошибки, а не адаптера
    await expect(provider.analyzeReviews(request)).rejects.toBeInstanceOf(LlmError);
  });
});

