    },
    promptVersion: config.llmPromptVersion,
    samplingVersion: config.llmSamplingVersion,
    minReviews: config.llmMinReviews,
    retryCount: config.llmRetryCount,
    maxOutputTokens: config.llmMaxOutputTokens,
  });
}
"""
