    const { rows } = await this.pool.query<{
      total: string;
      succeeded: string;
      partial: string;
      failed: string;
      in_progress: string;
    }>(
      `WITH classified AS (
         SELECT
           status,
           EXISTS (
             SELECT 1
             FROM jsonb_each(stages) AS stage(name, state)
             WHERE stage.name NOT IN ('fetchGame', 'fetchReviews')
               AND state->>'status' IN ('failed', 'skipped')
           ) AS has_optional_gap
         FROM daily_claims
         WHERE run_id = $1
       )
       SELECT
         count(*)::text AS total,
         count(*) FILTER (
           WHERE status = 'done' AND NOT has_optional_gap
         )::text AS succeeded,
         count(*) FILTER (
           WHERE status = 'done' AND has_optional_gap
         )::text AS partial,
         count(*) FILTER (WHERE status = 'failed')::text AS failed,
         count(*) FILTER (WHERE status IN ('pending', 'claimed'))::text AS in_progress
       FROM classified`,
      [runId],
    );

    const row = rows[0];
    return {
      total: Number(row?.total ?? 0),
      succeeded: Number(row?.succeeded ?? 0),
      partial: Number(row?.partial ?? 0),
      failed: Number(row?.failed ?? 0),
      inProgress: Number(row?.in_progress ?? 0),
    };
