/*
 * Базовые стили.
 *
 * Собственные, без UI-библиотеки: набор компонентов невелик, а зависимость
 * весом в сотни килобайт ради карточек и кнопок не оправдана.
 */

:root {
  --bg: #0f1116;
  --bg-elevated: #171a21;
  --bg-subtle: #1e222b;
  --border: #2a2f3a;
  --text: #e8eaed;
  --text-muted: #9aa3b2;
  --accent: #4c8dff;
  --accent-hover: #6ba0ff;

  /* Цвета оценок: зелёный/жёлтый/красный по шкале Metacritic */
  --score-high: #00ce7a;
  --score-mid: #ffbd3f;
  --score-low: #ff6874;

  --warn-bg: #2d2417;
  --warn-border: #6b5220;
  --warn-text: #f0c674;

  --radius: 10px;
  --space: 1rem;
  --max-width: 1200px;
}

@media (prefers-color-scheme: light) {
  :root {
    --bg: #f6f7f9;
    --bg-elevated: #ffffff;
    --bg-subtle: #eef0f4;
    --border: #d9dee6;
    --text: #16181d;
    --text-muted: #5b6472;
    --accent: #1a5fd0;
    --accent-hover: #14489e;

    --warn-bg: #fdf6e3;
    --warn-border: #e0c169;
    --warn-text: #7a5c12;
  }
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  /* Плавная прокрутка отключается для тех, кто просил уменьшить движение */
  scroll-behavior: smooth;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

h1,
h2,
h3 {
  line-height: 1.25;
  margin: 0 0 0.5em;
  font-weight: 650;
}

h1 {
  font-size: clamp(1.5rem, 4vw, 2.25rem);
}
h2 {
  font-size: clamp(1.2rem, 3vw, 1.5rem);
}
h3 {
  font-size: 1.05rem;
}

p {
  margin: 0 0 1em;
}

a {
  color: var(--accent);
  text-decoration: none;
}

a:hover {
  color: var(--accent-hover);
  text-decoration: underline;
}

/* Фокус виден всегда: без него навигация с клавиатуры невозможна */
:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 4px;
}

img {
  max-width: 100%;
  display: block;
}

/* Скрыто визуально, но доступно программам чтения с экрана */
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

/* Переход к содержимому — первый элемент в порядке обхода */
.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
  z-index: 100;
  padding: 0.75rem 1rem;
  background: var(--accent);
  color: #fff;
}

.skip-link:focus {
  left: 0;
}

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space);
}

.site-header {
  border-bottom: 1px solid var(--border);
  background: var(--bg-elevated);
  padding: 1rem 0;
  margin-bottom: 2rem;
}

.site-header__inner {
  display: flex;
  align-items: baseline;
  gap: 0.75rem;
