  --bg: #0f1116;
  --bg-elevated: #171a21;
  --bg-subtle: #1e222b;
  --border: #2a2f3a;
  --text: #e8eaed;
  --text-muted: #9aa3b2;
  --accent: #4c8dff;
  --accent-hover: #6ba0ff;

  /* Цвета оценок: зелёный/жёлтый/красный по шкале Metacritic */
  --score-high: #00ce7a;
  --score-mid: #ffbd3f;
  --score-low: #ff6874;

  --warn-bg: #2d2417;
  --warn-border: #6b5220;
  --warn-text: #f0c674;

  --radius: 10px;
  --space: 1rem;
  --max-width: 1200px;
}

@media (prefers-color-scheme: light) {
  :root {
    --bg: #f6f7f9;
    --bg-elevated: #ffffff;
    --bg-subtle: #eef0f4;
    --border: #d9dee6;
    --text: #16181d;
    --text-muted: #5b6472;
    --accent: #1a5fd0;
    --accent-hover: #14489e;

    --warn-bg: #fdf6e3;
    --warn-border: #e0c169;
    --warn-text: #7a5c12;
