.theme__name {
  font-weight: 650;
  font-size: 0.9375rem;
}

.theme__description {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin: 0;
}

/* --- Состояния --- */

.empty-state {
  text-align: center;
  padding: 3rem 1rem;
  color: var(--text-muted);
}

.empty-state__title {
  color: var(--text);
  margin-bottom: 0.5rem;
}

.notice {
  padding: 0.75rem 1rem;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--bg-subtle);
  font-size: 0.9375rem;
  color: var(--text-muted);
}

/* --- Пагинация --- */

.pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin-top: 2rem;
  flex-wrap: wrap;
}

.pagination__status {
  font-size: 0.875rem;
  color: var(--text-muted);
  font-variant-numeric: tabular-nums;
}

.pagination__spacer {
  display: inline-block;
  min-width: 5.5rem;
}

/* --- Загрузка --- */

.skeleton {
  background: linear-gradient(
    90deg,
    var(--bg-subtle) 25%,
    var(--border) 50%,
    var(--bg-subtle) 75%
  );
  background-size: 200% 100%;
  animation: shimmer 1.4s infinite;
  border-radius: var(--radius);
}

@keyframes shimmer {
  0% {
    background-position: 200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}

.skeleton--card {
  aspect-ratio: 3 / 4;
}

.skeleton--text {
  height: 1rem;
  margin-top: 0.5rem;
}

