1	import 'server-only';
2	
3	import type {
4	  GameAnalysis,
5	  GameDetail,
6	  GameListItem,
7	  Paged,
8	  PlatformOption,
9	  SortField,
10	  SortOrder,
11	} from './types.js';
12	
13	/**
14	 * Клиент API. Выполняется ТОЛЬКО на сервере.
15	 *
16	 * Импорт 'server-only' превращает случайное использование в клиентском
17	 * компоненте в ошибку сборки: адрес бэкенда и заголовки не должны попадать
18	 * в браузерный пакет.
19	 *
20	 * Все обращения к бэкенду проходят здесь: fetch по компонентам не
21	 * разбрасывается.
22	 */
23	
24	/** Адрес бэкенда. Только серверная переменная — без префикса NEXT_PUBLIC_. */
25	function baseUrl(): string {
26	  return process.env.API_BASE_URL ?? 'http://127.0.0.1:3001';
27	}
28	
29	const DEFAULT_TIMEOUT_MS = Number(process.env.API_TIMEOUT_MS ?? 8000);
30	
31	/** Сбой обращения к API, приведённый к виду, пригодному для интерфейса. */
32	export class ApiRequestError extends Error {
33	  constructor(
34	    readonly status: number,
35	    readonly code: string,
36	    message: string,
37	    readonly requestId: string | null,
38	  ) {
39	    super(message);
40	    this.name = 'ApiRequestError';
41	  }
42	
43	  /** Ресурс отсутствует — интерфейс показывает страницу «не найдено». */
44	  get isNotFound(): boolean {
45	    return this.status === 404;
46	  }
47	}
48	
49	interface RequestOptions {
50	  /**
51	   * Время жизни кеша в секундах.
52	   *
53	   * Данные меняются после обхода источника и анализа, поэтому кеш
54	   * недолгий и задаётся явно для каждого запроса. Бесконтрольное
55	   * кеширование показывало бы устаревшие оценки.
56	   */
57	  readonly revalidate: number;
58	}
59	
60	async function request<T>(
61	  path: string,
62	  options: RequestOptions,
63	): Promise<T> {
64	  const url = `${baseUrl()}${path}`;
65	
66	  let response: Response;
67	  try {
68	    response = await fetch(url, {
69	      headers: { accept: 'application/json' },
70	      next: { revalidate: options.revalidate },
71	      signal: AbortSignal.timeout(DEFAULT_TIMEOUT_MS),
72	    });
73	  } catch {
74	    // Сетевой сбой или таймаут. Исходную ошибку наружу не передаём:
75	    // её текст содержит адрес бэкенда, который клиенту знать незачем.
76	    throw new ApiRequestError(503, 'NETWORK_ERROR', 'Сервис временно недоступен', null);
77	  }
78	
79	  if (!response.ok) {
80	    // Тело ошибки уже безопасно: бэкенд не кладёт туда ни трассировку,
81	    // ни секреты (docs/API.md §2).
82	    let code = 'HTTP_ERROR';
83	    let message = 'Не удалось получить данные';
84	    let requestId: string | null = response.headers.get('x-request-id');
85	
86	    try {
87	      const body = (await response.json()) as {
88	        error?: { code?: string; message?: string; requestId?: string };
89	      };
90	      if (body.error?.code) code = body.error.code;
91	      if (body.error?.message) message = body.error.message;
92	      if (body.error?.requestId) requestId = body.error.requestId;
93	    } catch {
94	      // Ответ без JSON-тела — оставляем общие значения.
95	    }
96	
97	    throw new ApiRequestError(response.status, code, message, requestId);
98	  }
99	
100	  return (await response.json()) as T;
101	}
102	
103	export interface GameListParams {
104	  readonly page?: number;
105	  readonly pageSize?: number;
106	  readonly q?: string;
107	  readonly platform?: string;
108	  readonly sort?: SortField;
109	  readonly order?: SortOrder;
110	}
111	
112	/** Собирает строку запроса, пропуская пустые значения. */
113	function buildQuery(params: Record<string, string | number | undefined>): string {
114	  const search = new URLSearchParams();
115	  for (const [key, value] of Object.entries(params)) {
116	    if (value !== undefined && value !== '') search.set(key, String(value));
117	  }
118	  const query = search.toString();
119	  return query ? `?${query}` : '';
120	}
121	
122	export async function fetchGames(
123	  params: GameListParams = {},
124	): Promise<Paged<GameListItem>> {
125	  const query = buildQuery({
126	    page: params.page,
127	    pageSize: params.pageSize,
128	    q: params.q,
129	    platform: params.platform,
130	    sort: params.sort,
131	    order: params.order,
132	  });
133	
134	  // Каталог обновляется после ежечасного обхода: минуты достаточно,
135	  // чтобы снять нагрузку и не показывать заметно устаревшие данные.
136	  return request<Paged<GameListItem>>(`/api/games${query}`, { revalidate: 60 });
137	}
138	
139	export async function fetchGame(id: string): Promise<GameDetail> {
140	  return request<GameDetail>(`/api/games/${encodeURIComponent(id)}`, {
141	    revalidate: 60,
142	  });
143	}
144	
145	export async function fetchAnalysis(id: string): Promise<GameAnalysis> {
146	  // Анализ меняется реже каталога, но привязан к той же карточке.
147	  return request<GameAnalysis>(`/api/games/${encodeURIComponent(id)}/analysis`, {
148	    revalidate: 300,
149	  });
150	}
151	
152	export async function fetchPlatforms(): Promise<{ items: readonly PlatformOption[] }> {
153	  // Список платформ практически статичен.
154	  return request<{ items: readonly PlatformOption[] }>('/api/platforms', {
155	    revalidate: 3600,
156	  });
157	}

