41	  readonly outcome: 'success' | 'partial' | 'failed';
42	  readonly stages: readonly StageReport[];
43	  /** Карта стадий для сохранения в заявке. */
44	  readonly stageMap: StageMap;
45	  readonly errorCategory: string | null;
46	  readonly errorMessage: string | null;
47	}
48	
49	export interface ProcessGamePipelineDeps {
50	  readonly ingestGame: IngestGameUseCase;
51	  /** Синхронизация отзывов критиков и пользователей. */
52	  readonly syncCriticReviews: SyncReviewsUseCase;
53	  readonly syncUserReviews: SyncReviewsUseCase;
54	  /**
55	   * Разбор отзывов. null означает, что анализ выключен конфигурацией —
56	   * это штатное состояние, а не ошибка.
57	   */
58	  readonly analyzeReviews: AnalyzeReviewsUseCase | null;
59	  readonly events?: IngestionEventSink;
60	  readonly now: () => Date;
61	  /**
62	   * Платформа для анализа. Резюме хранится по (игра, вид, платформа);
63	   * конвейер разбирает отзывы без разбивки по платформам.
64	   */
65	  readonly analysisPlatform: string;
66	}
