74	/** Ошибка стадии, приведённая к безопасному для журнала виду. */
75	function describeError(error: unknown): { category: string; message: string } {
76	  if (isIngestionError(error)) {
77	    return { category: error.category, message: error.message };
78	  }
79	
80	  // Категория неизвестна — но текст ошибки не расширяем: он может
81	  // содержать фрагменты ответа источника.
82	  return {
83	    category: 'unknown',
