/**
 * Сборка объединённого журнала AI-переписки.
 *
 * Из сырых записей берутся только содержательные (user/assistant/system)
 * и приводятся к единому виду: agent, role, timestamp, eventType.
 * Сырой журнал при этом не изменяется — merged строится рядом.
 */
const fs = require('fs');
const path = require('path');

const RAW_DIR = 'logs/ai/raw';
const OUT = 'logs/ai/merged/conversation.jsonl';

const KEEP = new Set(['user', 'assistant', 'system']);

/** Текст сообщения: массив блоков либо строка. */
function extractText(message) {
  if (!message) return null;
  const c = message.content;
  if (typeof c === 'string') return c;
  if (!Array.isArray(c)) return null;

  const parts = [];
  for (const block of c) {
    if (block?.type === 'text' && typeof block.text === 'string') parts.push(block.text);
    else if (block?.type === 'tool_use') parts.push(`[tool_use: ${block.name}]`);
    else if (block?.type === 'tool_result') parts.push('[tool_result]');
    else if (block?.type === 'thinking') parts.push('[thinking]');
  }
  return parts.length ? parts.join('\n') : null;
}

const out = [];
for (const file of fs.readdirSync(RAW_DIR).filter((f) => f.endsWith('.jsonl'))) {
  const lines = fs.readFileSync(path.join(RAW_DIR, file), 'utf8').split('\n').filter(Boolean);

  for (const line of lines) {
    let e;
    try { e = JSON.parse(line); } catch { continue; }
    if (!KEEP.has(e.type)) continue;

    const text = extractText(e.message);

    out.push({
      agent: 'claude-code',
      role: e.type,
      timestamp: e.timestamp ?? null,
      eventType: e.type,
      sessionId: e.sessionId ?? null,
      uuid: e.uuid ?? null,
      model: e.message?.model ?? null,
      text,
      sourceFile: file,
    });
  }
}

// Порядок по времени; записи без времени сохраняют исходный порядок
out.sort((a, b) => String(a.timestamp ?? '').localeCompare(String(b.timestamp ?? '')));

fs.writeFileSync(OUT, out.map((r) => JSON.stringify(r)).join('\n') + '\n', 'utf8');
console.log('записей в merged:', out.length);
EOF
