const fs=require('fs'),path=require('path');
const RAW='logs/ai/raw',OUT='logs/ai/merged/conversation.jsonl';
const KEEP=new Set(['user','assistant','system']);
function txt(m){if(!m)return null;const c=m.content;if(typeof c==='string')return c;if(!Array.isArray(c))return null;
const p=[];for(const b of c){if(b?.type==='text'&&typeof b.text==='string')p.push(b.text);
else if(b?.type==='tool_use')p.push('[tool_use: '+b.name+']');else if(b?.type==='tool_result')p.push('[tool_result]');
else if(b?.type==='thinking')p.push('[thinking]');}return p.length?p.join('\n'):null;}
const out=[];
for(const f of fs.readdirSync(RAW).filter(x=>x.endsWith('.jsonl'))){
for(const l of fs.readFileSync(path.join(RAW,f),'utf8').split('\n').filter(Boolean)){
let e;try{e=JSON.parse(l)}catch{continue}if(!KEEP.has(e.type))continue;
out.push({agent:'claude-code',role:e.type,timestamp:e.timestamp??null,eventType:e.type,
sessionId:e.sessionId??null,uuid:e.uuid??null,model:e.message?.model??null,text:txt(e.message),sourceFile:f});}}
out.sort((a,b)=>String(a.timestamp??'').localeCompare(String(b.timestamp??'')));
fs.writeFileSync(OUT,out.map(r=>JSON.stringify(r)).join('\n')+'\n','utf8');
console.log('  merged пересобран: '+out.length+' записей');
EOF
